import 'package:flutter/material.dart'; import '../../models/message.dart'; import '../../repositories/chat_repository.dart';
class ChatScreen extends StatefulWidget{final String conversationId;const ChatScreen({super.key,this.conversationId='demo-conversation'});@override State<ChatScreen>createState()=>_ChatScreenState();}
class _ChatScreenState extends State<ChatScreen>{final repo=ChatRepository();final input=TextEditingController();final List<Message>items=[];bool busy=true;@override void initState(){super.initState();load();}Future<void>load()async{final x=await repo.messages(widget.conversationId);if(mounted)setState((){items..clear()..addAll(x);busy=false;});}Future<void>send()async{final text=input.text.trim();if(text.isEmpty)return;input.clear();final m=await repo.send(widget.conversationId,text);if(m!=null&&mounted)setState(()=>items.add(m));} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Chat')),body:Column(children:[Expanded(child:busy?const Center(child:CircularProgressIndicator()):ListView.builder(padding:const EdgeInsets.all(12),itemCount:items.length,itemBuilder:(_,i)=>Align(alignment:Alignment.centerRight,child:Card(child:Padding(padding:const EdgeInsets.all(10),child:Text(items[i].content)))))),SafeArea(child:Row(children:[Expanded(child:TextField(controller:input,maxLength:2000,decoration:const InputDecoration(hintText:'Message',border:InputBorder.none,contentPadding:EdgeInsets.all(12)))),IconButton(onPressed:send,icon:const Icon(Icons.send))]))]));}
